    shortDescription: {
      fi: 'Aqtaun rantakatu — veistospolku, näköalalavat ja Kaspianmeren rannat keskellä kaupunkia.',
      en: 'Aktau\'s seafront — a sculpture trail, viewing decks and the shores of the Caspian Sea right in the city.',
      ru: 'Набережная Актау — аллея со скульптурами, смотровые площадки и берега Каспийского моря в центре города.',
      kk: 'Ақтау жағалауы — мүсіндер соқпағы, шолу алаңдары және қаланың ортасындағы Каспий теңізінің жағалаулары.',
    },
    description: {
      fi: 'Skalnaya tropa eli "Kallinpolku" kulkee noin 1,5 km matkalla rosoista rantakallioilta, ja sen varrelle on rakennettu parikymmentä näköalalavaa, taustamusiikki ja iltavalaistus. Veistoksia löytyy ympäri promenadia — tunnetuin on "Kahdeksan rakkauden käskyä" -ryhmä ja "I love Aktau" -kyltti, jotka ovat suosittuja valokuvauspaikkoja.\n\nIlta-aurinko Kaspianmeren yllä on Aqtaun klassinen show: paikalliset tulevat kävelylle, jäätelölle ja katselemaan auringonlaskua. Rantakadun varrella on useita kahviloita ja jäätelöbaareja, ja keskustaan pääsee kävellen tai Yandex Go -taksilla muutamalla satasella tengeellä.',
      en: 'The Skalnaya Tropa, or "Cliff Path", runs about 1.5 km along the rugged coastal cliffs, lined by some twenty viewing decks, background music and evening lighting. Sculptures are scattered along the promenade — the best known is the "Eight Commandments of Love" group and the "I love Aktau" sign, both popular photo spots.\n\nThe evening sun over the Caspian Sea is Aktau\'s classic show: locals come out to walk, eat ice cream and watch the sunset. The promenade has several cafés and ice cream bars, and the city centre is within walking distance or just a couple of hundred tenge by Yandex Go.',
      ru: 'Скальная тропа протяжённостью около 1,5 км идёт по неровным прибрежным обрывам, вдоль неё установлено около двух десятков смотровых площадок, играет фоновая музыка и работает вечерняя подсветка. По всему променаду расставлены скульптуры — самые известные — группа «Восемь заповедей любви» и табличка «I love Aktau», популярные места для фото.\n\nВечернее солнце над Каспийским морем — классическое шоу Актау: местные выходят прогуляться, поесть мороженого и посмотреть закат. Вдоль набережной много кафе и точек с мороженым, а до центра города можно дойти пешком или доехать на Yandex Go за пару сотен тенге.',
      kk: '«Жартас соқпағы» (Скальная тропа) шамамен 1,5 км бойы кедір-бұдыр жағалаудағы жартастар арқылы өтеді; бойында жиырмаға жуық шолу алаңы, фондық музыка және кешкі жарықтандыру бар. Жағалау бойымен мүсіндер шашылған — ең танымалы «Махаббаттың сегіз өсиеті» тобы мен «I love Aktau» жазуы, бұлар суретке түсуге сүйікті орындар.\n\nКаспий теңізінің үстіндегі кешкі күн — Ақтаудың классикалық қойылымы: жергілікті тұрғындар серуендеуге, балмұздақ жеуге және күн батуын тамашалауға шығады. Жағалауда бірнеше кафе мен балмұздақ дүкендері бар, ал қала орталығына жаяу немесе бірнеше жүз теңгеге Yandex Go таксиімен жетуге болады.',
    },
