    nameLocal: 'Тамшалы',
    category: 'nature',
    region: 'aktau',
    coords: { lat: 44.5484, lng: 50.6773 },
    shortDescription: {
      fi: 'Pohjoisen Mangystaun salainen kanjoni — vesiputous, lähteitä ja makean veden lampi.',
      en: 'A hidden canyon in northern Mangystau — a waterfall, springs and a freshwater pool.',
      ru: 'Скрытый каньон на севере Мангистау — водопад, источники и пресноводный пруд.',
      kk: 'Маңғыстаудың солтүстігіндегі құпия шатқал — сарқырама, бұлақтар және тұщы су тоғаны.',
    },
    description: {
      fi: 'Tamshaly on noin 10–12 km pitkä kanjoni Mangystaun Tupkaragan-niemen pohjoisosassa, noin 30 km Fort-Shevchenkosta itään. Kanjonin pohjalla tipahtelevat lähteet ja pieni vesiputous luovat keidasvyöhykkeen kuivaan kalkkikivimaisemaan; lähde "tamshaly" tarkoittaa kazakiksi tipahtelevaa.\n\nPaikka on hiljaisempi kuin etelän tunnetut kohteet, eikä turistiryhmiä juuri näy. Aqtausta ajo on pitkä — noin 200 km pohjoiseen — joten varhainen lähtö on välttämätön ja yhdistäminen Fort-Shevchenkon vanhaan kalmistoon tai Cape Zhygylganiin kannattaa. Reitti on enimmäkseen asfalttia, viimeiset kilometrit soratietä.',
      en: 'Tamshaly is a roughly 10–12 km canyon in the northern part of the Tupkaragan peninsula in Mangystau, about 30 km east of Fort-Shevchenko. Dripping springs and a small waterfall on the canyon floor form an oasis belt in the dry limestone landscape; the word "tamshaly" means "dripping" in Kazakh.\n\nThe place is quieter than the well-known southern sites and tour groups are rarely seen here. The drive from Aktau is long — about 200 km north — so an early start is essential, and it pays to combine the trip with Fort-Shevchenko\'s old necropolis or Cape Zhygylgan. The route is mostly paved, with the last few kilometres on gravel.',
      ru: 'Тамшалы — каньон длиной около 10–12 км на севере полуострова Тупкараган в Мангистау, примерно в 30 км к востоку от Форт-Шевченко. Капающие источники и небольшой водопад на дне каньона образуют оазисный пояс посреди сухого известнякового ландшафта; слово «тамшалы» по-казахски означает «капающий».\n\nМесто тише, чем известные южные точки, и туристических групп здесь практически не бывает. Дорога из Актау длинная — около 200 км на север, поэтому ранний выезд обязателен, и поездку стоит совмещать со старым некрополем Форт-Шевченко или мысом Жыгылган. Маршрут в основном по асфальту, последние километры — по гравию.',
      kk: 'Тамшалы — Маңғыстаудың Түпқараған түбегінің солтүстігіндегі, Форт-Шевченкодан шамамен 30 км шығыста жатқан 10–12 км ұзындықтағы шатқал. Шатқал түбіндегі тамшылаған бұлақтар мен шағын сарқырама құрғақ әктасты ландшафтта алқап белдеуін құрайды; «тамшалы» сөзі қазақ тілінде «тамшылайтын» дегенді білдіреді.\n\nБұл жер оңтүстіктегі белгілі орындарға қарағанда тыныш, мұнда туристік топтар сирек кездеседі. Ақтаудан жол ұзақ — солтүстікке қарай шамамен 200 км — сондықтан ерте шығу міндетті, әрі сапарды Форт-Шевченконың ескі қорымымен немесе Жығылған мүйісімен біріктірген жөн. Бағыт негізінен асфальт, соңғы шақырымдары — қиыршық тас.',
    },
