      fi: 'Maailman suurin pallorakennus — 8 kerrosta uusiutuvan energian museota lasipallon sisällä.',
      en: 'The world\'s largest spherical building — eight floors of a renewable-energy museum inside a glass sphere.',
      ru: 'Самое большое сферическое здание в мире — 8 этажей музея возобновляемой энергии внутри стеклянного шара.',
      kk: 'Әлемдегі ең үлкен шар тәрізді ғимарат — шыны сфераның ішіндегі жаңартылатын энергия мұражайының 8 қабаты.',
