      fi: 'EXPO 2017 -näyttelyn pääpaviljonki, halkaisijaltaan 80 m ja korkeudeltaan 100 m. Sisällä Tulevaisuuden energian museo, jonka kahdeksan kerrosta käyvät vuorollaan läpi avaruuden, auringon, tuulen, biomassan, kineettisen ja veden energiamuodot. Adrian Smith + Gordon Gill -arkkitehtien suunnittelema.\n\nYläkerroksen "Astana of the Future" -visio on parhaiten kuratoitu osio, ja ylimmästä kerroksesta avautuu näköala koko EXPO-alueen yli. Kannattaa varata 2–3 tuntia rauhassa.',
      en: 'The main pavilion of EXPO 2017, 80 m in diameter and 100 m tall. Inside is the Museum of Future Energy, whose eight floors explore the energies of space, the sun, wind, biomass, kinetic energy and water in turn. Designed by architects Adrian Smith + Gordon Gill.\n\nThe top-floor "Astana of the Future" vision is the best-curated section, and the uppermost floor opens up a view across the entire EXPO grounds. Plan to spend 2–3 unhurried hours here.',
      ru: 'Главный павильон выставки ЭКСПО-2017, диаметром 80 м и высотой 100 м. Внутри — Музей энергии будущего, восемь этажей которого по очереди раскрывают энергию космоса, солнца, ветра, биомассы, кинетическую и водную. Здание спроектировано архитекторами Adrian Smith + Gordon Gill.\n\nЛучше всего проработан раздел верхнего этажа "Астана будущего", а с самой верхней точки открывается вид на всю территорию ЭКСПО. Заложите 2–3 спокойных часа на посещение.',
      kk: 'ЭКСПО 2017 көрмесінің бас павильоны, диаметрі 80 м, биіктігі 100 м. Ішінде Болашақ энергиясы мұражайы орналасқан, оның сегіз қабаты ғарыш, күн, жел, биомасса, кинетикалық және су энергиясын кезек-кезек ашып көрсетеді. Сәулетшілер Adrian Smith + Gordon Gill жобасы.\n\nЕң жоғарғы қабаттағы "Болашақ Астанасы" көрмесі ең сапалы құрастырылған бөлім, ал ең жоғарғы қабаттан бүкіл ЭКСПО аумағына көрініс ашылады. 2–3 сағат бөліп, асықпай тамашалаған жөн.',
