    shortDescription: {
      fi: 'Keski-Aasian suurimpia museoita — 7 salin matka kivikaudesta moderniin Kazakstaniin.',
      en: 'One of Central Asia\'s largest museums — a journey through 7 halls from the Stone Age to modern Kazakhstan.',
      ru: 'Один из крупнейших музеев Центральной Азии — путешествие по 7 залам от каменного века до современного Казахстана.',
      kk: 'Орталық Азиядағы ең үлкен мұражайлардың бірі — тас дәуірінен бүгінгі Қазақстанға дейінгі 7 залдан өтетін саяхат.',
    },
    description: {
      fi: 'Vuonna 2014 avattu museo Tauelsizdik-aukiolla on yli 70 000 m²:n kokoinen ja yksi koko Keski-Aasian suurimmista. Salit kattavat arkeologian, antiikin, etnografian, modernin historian ja itsenäisyyden ajan. Tunnetuimpia esineitä on jäljennös Issykin "Kultaisesta miehestä".\n\nMuseo sopii loistavasti sateiselle tai polttavalle päivälle, ja se on kävelyetäisyydellä Hazret Sultan -moskeijasta sekä Rauhan palatsista — voitte yhdistää kaikki yhden iltapäivän aikana.',
      en: 'Opened in 2014 on Tauelsizdik (Independence) Square, the museum spans more than 70,000 m² and is one of the largest in all of Central Asia. The halls cover archaeology, antiquity, ethnography, modern history and the era of independence. One of the most famous exhibits is a replica of the "Golden Man" from Issyk.\n\nThe museum is a great choice on a rainy or scorching day, and it is within walking distance of the Hazret Sultan Mosque and the Palace of Peace — you can combine all three into a single afternoon.',
      ru: 'Открытый в 2014 году музей на площади Тауелсиздик занимает более 70 000 м² и является одним из крупнейших во всей Центральной Азии. Залы охватывают археологию, древность, этнографию, новейшую историю и эпоху независимости. Среди самых известных экспонатов — копия иссыкского "Золотого человека".\n\nМузей прекрасно подходит для дождливого или знойного дня, а до мечети Хазрет Султан и Дворца мира можно дойти пешком — всё это можно совместить в одно послеобеденное время.',
      kk: '2014 жылы Тәуелсіздік алаңында ашылған мұражайдың ауданы 70 000 м²-ден асады және ол бүкіл Орталық Азиядағы ең үлкендердің бірі. Залдар археологияны, ежелгі дәуірді, этнографияны, жаңа тарихты және тәуелсіздік кезеңін қамтиды. Ең танымал экспонаттардың бірі — Есіктен табылған "Алтын адамның" көшірмесі.\n\nМұражай жаңбырлы немесе аптап ыстық күнге өте қолайлы, әрі Хазірет Сұлтан мешіті мен Бейбітшілік сарайынан жаяу жүретін қашықтықта — осының бәрін бір түскі мезгілде үйлестіруге болады.',
    },
