    shortDescription: {
      fi: 'Avoin pienoismalli koko Kazakstanista — 1,7 hehtaarin maa-asemoitu kartta nähtävyyksineen.',
      en: 'An open-air miniature of the whole of Kazakhstan — a 1.7-hectare geographically positioned map with its landmarks.',
      ru: 'Открытый миниатюрный макет всего Казахстана — карта на 1,7 га, привязанная к местности, с достопримечательностями.',
      kk: 'Бүкіл Қазақстанның ашық аспан астындағы кіші макеті — нысаналары бар, жер бедеріне сәйкес 1,7 гектарлық карта.',
    },
    description: {
      fi: 'Vuonna 2001 avattu etnografinen ulkomuseo on käytännössä koko Kazakstanin kartta pienoiskoossa: jokainen alueen ikoni — vuoret, mausoleumit, kaupungit, infrastruktuuri — on rakennettu mittakaavassa kahden hehtaarin alueelle. Yli 400 yksityiskohtaa, ja kokoelma kasvaa edelleen.\n\nLoistaa erityisesti reissun alussa: yhdellä kävelyllä saatte kuvan siitä, mitä alueita maassa on ja missä isot kohteet sijaitsevat. Vie noin 1,5–2 tuntia rauhassa.',
      en: 'Opened in 2001, this ethnographic open-air museum is essentially a miniature map of the entire country: every regional icon — mountains, mausoleums, cities, infrastructure — has been built to scale across a two-hectare site. There are more than 400 details, and the collection keeps growing.\n\nIt shines especially at the start of a trip: in a single walk you get a sense of the country\'s regions and where the big sights are located. Allow about 1.5–2 unhurried hours.',
      ru: 'Открытый в 2001 году этнографический музей под открытым небом — это, по сути, миниатюрная карта всей страны: каждая региональная икона — горы, мавзолеи, города, инфраструктура — выполнена в масштабе на участке в два гектара. Более 400 деталей, и коллекция продолжает расти.\n\nОсобенно хорош в начале поездки: за одну прогулку вы получаете представление о регионах страны и о том, где находятся главные достопримечательности. Заложите 1,5–2 спокойных часа.',
      kk: '2001 жылы ашылған этнографиялық ашық аспан астындағы мұражай — іс жүзінде бүкіл Қазақстанның кіші макет картасы: әр өңірдің таңбасы — таулар, кесенелер, қалалар, инфрақұрылым — екі гектарлық алаңда масштабпен жасалған. 400-ден астам деталь бар, әрі коллекция әлі толығып келеді.\n\nӘсіресе сапардың басында тамаша: бір серуенмен елдің қандай өңірлері бар екенін және ірі нысандар қайда орналасқанын аңғарасыз. Асықпай 1,5–2 сағат бөлген жөн.',
    },
