      ru: 'Лучше всего сохранившиеся городские руины Шёлкового пути — стены высотой 6 м и подземная система водоснабжения кяриз.',
      kk: 'Жібек жолының ең жақсы сақталған қала қирандылары — биіктігі 6 м қабырғалар мен кәріз жер асты су жүйесі.',
