      ru: 'Памятник наскального искусства на берегу реки Или, примерно в 170 км к северо-западу от Алматы. Более 5000 петроглифов от бронзового века до наших дней, а также редкие рельефы XII века с изображениями буддийских божеств (Будды, Бодхисаттвы), высеченные тибетскими монахами во время их путешествия.\n\nВнимание: это Тамгалы-Тас на берегу реки Или — НЕ путать с охраняемым ЮНЕСКО комплексом петроглифов Танбалы (Тамгалы), который находится примерно в 70 км западнее.',
