      en: 'A relict Sogdian ash forest in Charyn National Park — a plant community surviving from 25 million years ago.',
      ru: 'Реликтовая роща согдийского ясеня в национальном парке Чарын — растительное сообщество, сохранившееся с эпохи 25 миллионов лет назад.',
