      fi: 'Charynin kansallispuiston pohjoisosassa sijaitseva reliktinen Sogdian saarni (Fraxinus sogdiana) -metsä, joka on jäänteenä 25 miljoonan vuoden takaisesta lämpimämmästä Kazakstanista. Puut ovat 30–35 m korkeita, halkaisijaltaan yli 2 m, jotkut yli 300 vuotta vanhoja. Kasvaa villinä vain täällä ja Temirlik-rotkossa — paleobotaaninen maailmanharvinaisuus.\n\nKun käytte Charynin kanjonilla, älkää kääntykö heti takaisin — lehto on 15–20 min autolla pohjoisempana ja antaa kanjonipäivälle täysin erilaisen ekologisen tason.',
      en: 'A relict Sogdian ash (Fraxinus sogdiana) forest in the northern part of Charyn National Park, a remnant of the warmer Kazakhstan of 25 million years ago. Trees reach 30–35 m tall and over 2 m in diameter, some more than 300 years old. It grows wild only here and in the Temirlik Canyon — a paleobotanical rarity on a global scale.\n\nWhen you visit Charyn Canyon, don\'t turn back too soon — the grove is just 15–20 minutes north by car and adds a completely different ecological layer to your Charyn day.',
      ru: 'Реликтовая роща согдийского ясеня (Fraxinus sogdiana) в северной части национального парка Чарын — наследие более тёплого Казахстана 25 миллионов лет назад. Высота деревьев 30–35 м, диаметр более 2 м, некоторым более 300 лет. В диком виде растёт только здесь и в Темирликском каньоне — палеоботаническая редкость мирового масштаба.\n\nКогда вы посещаете Чарынский каньон, не спешите возвращаться — роща находится в 15–20 минутах езды севернее и придаёт дню в Чарыне совершенно иное экологическое измерение.',
      kk: 'Шарын ұлттық саябағының солтүстік бөлігіндегі соғды шағанының (Fraxinus sogdiana) реликті тоғайы — 25 миллион жыл бұрынғы жылырақ Қазақстанның қалдығы. Ағаштардың биіктігі 30–35 м, диаметрі 2 м-ден асады, кейбіреулері 300 жылдан асқан. Жабайы күйде тек осы жерде және Темірлік шатқалында өседі — әлемдік деңгейдегі палеоботаникалық сирек ескерткіш.\n\nШарын шатқалына барған кезде бірден қайтуға асықпаңыз — тоғай көлікпен 15–20 минут солтүстікте орналасқан және Шарын күніне мүлде басқа экологиялық қабат қосады.',
