      ru: 'Казахская соколиная охота, внесённая в список ЮНЕСКО, в живом исполнении — шоу в 17:00 (выходной — понедельник).',
      kk: 'ЮНЕСКО қорғауындағы қазақ саятшылығын тірі көрсету — күн сайын сағат 17:00-де (дүйсенбіде жабық).',
