    shortDescription: {
      fi: 'Neuvostoliiton suurin gulag-keskus + Spasskin suomalaismuistomerkki jatkosotavangille.',
      en: 'The largest Gulag complex in the Soviet Union, plus the Finnish memorial in Spassk to Continuation War prisoners.',
      ru: 'Крупнейший лагерный комплекс ГУЛАГа в СССР и финский мемориал в Спасске военнопленным Войны-продолжения.',
      kk: 'КСРО-дағы ГУЛАГ-тың ең үлкен кешені және Спасскідегі Жалғасу соғысының тұтқындарына арналған фин мемориалы.',
    },
    description: {
      fi: 'Karlag oli Neuvostoliiton suurin gulag-keskus — noin miljoona vankia läpäisi sen 1931–1959. Dolinkan museossa on hallintorakennus "Stalinin imperiumi"-tyyliin, rekonstruoidut sellit ja kidutushuoneet. Spasskissa 35 km kaakkoon on noin 5 000 sotavangin joukkohauta sekä Suomen, Saksan, Puolan, Japanin yms. kansallisia muistomerkkejä — Suomen muistomerkki jatkosotavangille on suomalaiselle koskettava.\n\nKaraganda itse on "honest Soviet city" -näyte: Kaivosmiesten kulttuuripalatsi Stalin Empire -tyylillä, Mining Glory -muistomerkki.',
      en: 'Karlag was the largest Gulag complex in the Soviet Union — roughly a million prisoners passed through between 1931 and 1959. The Dolinka museum occupies the former Stalin Empire–style administration building and includes reconstructed cells and torture rooms. In Spassk, 35 km to the southeast, a mass grave holds some 5,000 prisoners of war, surrounded by national memorials raised by Finland, Germany, Poland, Japan and others — the Finnish memorial to Continuation War prisoners is especially moving for Finnish visitors.\n\nKaraganda itself is a textbook "honest Soviet city": the Miners\' Palace of Culture in Stalin Empire style and the Mining Glory monument.',
      ru: 'Карлаг был крупнейшим лагерным комплексом ГУЛАГа в Советском Союзе — через него с 1931 по 1959 год прошло около миллиона заключённых. В музее в Долинке сохранилось административное здание в стиле сталинского ампира, реконструированные камеры и пыточные. В Спасске в 35 км к юго-востоку находится братская могила примерно 5 000 военнопленных и национальные мемориалы Финляндии, Германии, Польши, Японии и других стран — финский мемориал военнопленным Войны-продолжения особенно трогателен для финна.\n\nСама Караганда — образец "честного советского города": Дворец культуры горняков в стиле сталинского ампира и монумент Шахтёрской славы.',
      kk: 'Қарлаг — КСРО-дағы ГУЛАГ-тың ең үлкен кешені болды, 1931–1959 жылдары шамамен миллион тұтқын одан өтті. Долинка музейінде "Сталиндік ампир" стиліндегі әкімшілік ғимарат, қалпына келтірілген камералар мен азаптау бөлмелері сақталған. Оңтүстік-шығысқа қарай 35 км жердегі Спасскіде шамамен 5 000 әскери тұтқынның бауырластар қабірі және Финляндияның, Германияның, Польшаның, Жапонияның ұлттық мемориалдары бар — Жалғасу соғысының тұтқындарына арналған фин мемориалы фин адамы үшін ерекше әсерлі.\n\nҚарағандының өзі — "шынайы кеңестік қаланың" үлгісі: Сталиндік ампир стиліндегі Шахтерлер мәдениет сарайы және Кеншілер даңқы ескерткіші.',
    },
