      fi: 'Öljyhuippukaupunki Ural-joen suussa — 551 m Eurooppa–Aasia-jalankulkusilta keskellä kaupunkia.',
      en: 'Kazakhstan\'s oil capital at the mouth of the Ural River — a 551 m Europe–Asia pedestrian bridge crosses the city centre.',
      ru: 'Нефтяная столица Казахстана в устье реки Урал — пешеходный мост длиной 551 м соединяет Европу и Азию в центре города.',
      kk: 'Жайық өзенінің сағасындағы Қазақстанның мұнай астанасы — қала орталығында 551 м Еуропа–Азия жаяу жүргіншілер көпірі.',
