      ru: 'Более полумиллиона гектаров альпийских пейзажей, ледниковых рек, кедровых лесов и высочайших вершин Казахстана. Биосферный резерват ЮНЕСКО с 2014 года. Включает озеро Язевое (с видом на Белуху), Рахмановские горячие источники и скифские курганы Берель.\n\nДля района Рахманово и в сторону Белухи нужен пропуск в пограничную зону (оформление около 2 месяцев). На практике поездка бронируется через местного оператора. Реальный сезон — только июнь–сентябрь.',
