      ru: 'Старейший и крупнейший в мире космодром, арендованный Россией. Отсюда в 1961 году стартовал Юрий Гагарин. Космодром по-прежнему действует — продолжаются пилотируемые пуски "Союза". Казахстан объявил 2026 год годом посещения Байконура (новый туристский центр в Тюратаме, ожидаются более дешёвые пропуска).\n\nСтандартный 5-дневный тур стоит около 3 400 € с человека; тур с просмотром запуска — около 4 500 €; VIP — от 5 500 €. Копии паспортов нужны за 60 дней. После реформ 2026 года возможны более дешёвые однодневные поездки из Тюратама — проверяйте непосредственно перед поездкой.',
