      ru: 'Высокогорное озеро 38 × 19 км на высоте 1 447 м, окружённое тайгой, лугами и снежными вершинами. Заповедник площадью 71 300 га — 258 видов птиц, снежный барс, лось, медведь. Зимой до −55 °C, летом до +29 °C.\n\nСамое отдалённое "высокогорное озеро" Казахстана — никакой туристической инфраструктуры, только пара деревень и рыболовецкие станции. Подходит только для поездки, где главный фокус — Алтайский регион.',
      kk: '1 447 м биіктікте орналасқан, тайга, шалғын мен қарлы шыңдармен қоршалған 38 × 19 км биік таулы көл. 71 300 га қорық — 258 құс түрі, қар барысы, бұғы, аю. Қыста −55 °C, жазда +29 °C-қа дейін.\n\nҚазақстанның ең шалғай «биік таулы көлі» — туристік инфрақұрылым жоқ, бірнеше ауыл мен балық аулау станциялары ғана бар. Тек Алтай аймағы негізгі бағыт болған сапарға қолайлы.',
