      en: 'A 90 km stretch of free-standing white chalk outcrops on the Aktobe–Atyrau border. The best-known pinnacle, the "Queen", is named for its chess-piece shape. The rock contains fossilised shark teeth, ammonites and belemnites — this was once the floor of the Tethys Sea.\n\nThe Atyrau-region answer to Mangystau\'s chalk landscapes, but less known and more deserted. Requires a guided 4WD trip from Atyrau.',
      ru: 'Полоса протяжённостью 90 км из отдельно стоящих белых меловых останцов на границе Актюбинской и Атырауской областей. Самая известная вершина — "Королева" (Queen) — названа за форму шахматной фигуры. В породе сохранились окаменевшие зубы акул, аммониты, белемниты — это бывшее дно моря Тетис.\n\nАтырауский аналог меловых ландшафтов Мангистау, но менее известный и более безлюдный. Требуется организованная поездка на джипе из Атырау.',
      kk: 'Ақтөбе мен Атырау шекарасында 90 км-ге созылған, жеке-жеке тұрған ақ бор қалдықтары. Ең әйгілі шыңы — шахмат тасына ұқсас пішіні үшін «Королева» (Queen) деп аталады. Жыныста қалаған акула тістері, аммониттер, белемниттер сақталған — бұрынғы Тетис теңізінің түбі.\n\nМаңғыстаудың бор ландшафтарының Атыраулық баламасы, бірақ азырақ танымал әрі шалғайырақ. Атыраудан 4WD-гид саяхаты қажет.',
