    description: {
      fi: '1200-luvulla rakennettu sinikupolinen mausoleumi Tšingis-kaanin vanhimman pojan, Kultaisen ordan perustajan Jochi-khaanin haudalla. 2023 valmistui ympärillä 2 500 hehtaarin Jochi-khaanin historiallis-kulttuurinen kompleksi etnografisine kylineen.\n\nUlytau on Kazakstanin maantieteellinen ja symbolinen sydän — "shanyrak", missä khaanit kruunattiin. Lähes kukaan länsimainen turisti ei käy täällä.',
      en: 'A 13th-century blue-domed mausoleum over the grave of Jochi Khan, eldest son of Genghis Khan and founder of the Golden Horde. In 2023 a 2,500-hectare historical-cultural complex with an ethnographic village opened around the tomb.\n\nUlytau is the geographic and symbolic heart of Kazakhstan — the "shanyrak" where the khans were crowned. Almost no Western travellers reach it.',
      ru: 'Мавзолей с голубым куполом, построенный в XIII веке над могилой Джучи-хана — старшего сына Чингисхана и основателя Золотой Орды. В 2023 году вокруг него открылся историко-культурный комплекс площадью 2 500 га с этнографической деревней.\n\nУлытау — географическое и символическое сердце Казахстана, "шанырак", где короновали ханов. Западные туристы сюда почти не доезжают.',
      kk: 'XIII ғасырда салынған көк күмбезді кесене — Шыңғыс ханның үлкен ұлы, Алтын Орданың негізін қалаушы Жошы ханның басына тұрғызылған. 2023 жылы оның айналасында 2 500 гектарлық тарихи-мәдени кешен және этнографиялық ауыл ашылды.\n\nҰлытау — Қазақстанның географиялық және символдық жүрегі, хандар тағайындалған «шаңырақ». Бұл жерге Батыс туристері тек сирек ғана барады.',
    },
