    shortDescription: {
      fi: 'Tien Shanin marmoripyramidi (7 010 m) Kazakstanin, Kirgisian ja Kiinan rajalla — "Verikuningas" auringonlaskussa.',
      en: 'The marble pyramid of the Tien Shan (7,010 m) on the Kazakhstan–Kyrgyzstan–China border — the "Blood King" at sunset.',
      ru: 'Мраморная пирамида Тянь-Шаня (7 010 м) на стыке Казахстана, Киргизии и Китая — "Кровавый король" на закате.',
      kk: 'Тянь-Шаньның мәрмәр пирамидасы (7 010 м) — Қазақстан, Қырғызстан және Қытай шекарасында, күн батқанда «Қан патшасы».',
    },
    description: {
      fi: 'Tien Shanin tunnetuin huippu — terävä marmoripyramidi, jonka korkeus on 7 010 m jäätikkölakea myöten (kallioperä 6 995 m). Sijaitsee Kazakstanin, Kirgisian ja Kiinan rajakolmiossa, Almaty Regionin Raiymbekin piirissä. Auringonlaskussa marmorikuvut hehkuvat punaisena — siitä lempinimi "Verikuningas" (Кан Тегри).\n\nKlassikkokohde vuorikiipeilijöille (vakavasti 6 000+ m kokemusta) sekä trekkaajille, jotka tähtäävät Pohjoiselle tai Eteläiselle Inylchek-jäätikön base campille. Käytännössä reissu on 2–3 viikon ekspeditio operaattorin kautta — helikopterilla sisään tai useita päiviä Karkaran laaksosta. Vaatii rajavyöhykeluvan ja kokeneen oppaan.',
      en: 'The most famous peak of the Tien Shan — a sharp marble pyramid rising to 7,010 m to the top of its ice cap (bedrock at 6,995 m). It stands at the tri-border of Kazakhstan, Kyrgyzstan and China, in Raiymbek district of Almaty Region. At sunset the marble faces glow red — hence the local nickname "Blood King" (Kan Tengri).\n\nA classic objective for mountaineers (you need genuine 6,000 m+ experience) and for trekkers heading to the North or South Inylchek glacier base camps. In practice it is a 2–3 week expedition booked through an operator — flown in by helicopter or walked in over several days from the Karkara Valley. A border-zone permit and an experienced guide are mandatory.',
      ru: 'Самая известная вершина Тянь-Шаня — острая мраморная пирамида высотой 7 010 м по вершине ледовой шапки (скальная порода — 6 995 м). Находится на стыке границ Казахстана, Киргизии и Китая, в Райымбекском районе Алматинской области. На закате мраморные склоны раскаляются красным — отсюда местное прозвище "Кровавый король" (Кан-Тенгри).\n\nКлассическая цель для альпинистов (нужен реальный опыт на высотах 6 000+ м) и треккеров, идущих к базовым лагерям Северного или Южного Инылчека. На практике это экспедиция на 2–3 недели через оператора — заброска вертолётом или несколько дней пешком из долины Каркары. Обязательны пропуск в погранзону и опытный гид.',
      kk: 'Тянь-Шаньның ең әйгілі шыңы — мұз қалпағының ұшына дейін 7 010 м (тас негізі — 6 995 м) биіктікке көтерілетін үшкір мәрмәр пирамида. Қазақстан, Қырғызстан және Қытай шекараларының түйіскен жерінде, Алматы облысының Райымбек ауданында орналасқан. Күн батқан кезде мәрмәр беткейлер қызарып жайнайды — осыдан жергілікті атауы «Қан патшасы» (Хан Тәңірі) шыққан.\n\nАльпинистерге (нақты 6 000+ м тәжірибесі бар) және Солтүстік немесе Оңтүстік Іңілшек базалық лагеріне баратын треккерлерге арналған классикалық мақсат. Іс жүзінде бұл 2–3 апталық экспедиция, оператор арқылы ұйымдастырылады — тікұшақпен жеткізу немесе Қарқара аңғарынан бірнеше күн жаяу. Шекаралық рұқсат пен тәжірибелі гид міндетті.',
    },
