    shortDescription: {
      fi: 'Suljettu valtion luonnonsuojelualue Mangystaun eteläosassa — vain luvanvaraisesti oppaan kanssa.',
      en: 'A closed state nature reserve in southern Mangystau — accessible only with a permit and a guide.',
      ru: 'Закрытый государственный заповедник на юге Мангистау — только по разрешению и с проводником.',
      kk: 'Маңғыстаудың оңтүстігіндегі жабық мемлекеттік қорық — тек рұқсат пен гидпен ғана.',
    },
    description: {
      fi: 'Vuonna 1984 perustettu 223 000 hehtaarin valtion luonnonsuojelualue Ustyurtin ylätasangon eteläreunalla, Karakiyan piirissä. Suojelee aitoa Keski-Aasian autiomaa- ja arosteppiekosysteemiä: Ustyurtin urial-vuorikauris, Persian gaselli (jeyran), saiga, karakal ja historiallisesti gepardi. Maisema on karua kalkkikivitasankoa jyrkkine reunajyrkänteineen — eri kohde kuin pohjoisempi Bozzhyran kanjoniketju.\n\nReservi ei ole turistinähtävyys vaan tieteellinen suojelualue. Sisäänpääsy vaatii etukäteisluvan Metsä- ja eläinkunnan komitealta (Komitee de la Forêt) sekä paikallisen operaattorin tai reservin oman oppaan — walk-in ei onnistu. Käytännössä kohde sopii vain niille jotka haluavat erikoistunutta wildlife-watchingia ja jaksavat järjestää byrokratian etukäteen.',
      en: 'A 223,000-hectare state nature reserve established in 1984 on the southern rim of the Ustyurt Plateau, in Karakiya district. It protects a genuine Central Asian desert and arid-steppe ecosystem: the Ustyurt urial, Persian gazelle (jeyran), saiga, caracal, and historically the cheetah. The landscape is harsh limestone tableland with steep edge cliffs — quite distinct from the Bozzhyra canyon chain further north.\n\nThe reserve is a scientific protected area rather than a tourist sight. Entry requires advance permission from the Committee on Forestry and Wildlife and either a local operator or the reserve\'s own guide — walk-in visits are not possible. In practice it suits visitors who want specialised wildlife watching and are willing to handle the paperwork well in advance.',
      ru: 'Государственный природный заповедник площадью 223 000 га, созданный в 1984 году на южной кромке плато Устюрт, в Каракиянском районе. Охраняет настоящие центральноазиатские пустынные и аридно-степные экосистемы: устюртского уриала, джейрана, сайгу, каракала и исторически гепарда. Ландшафт — суровое известняковое плато с обрывистыми краями, не путать с северным каньонным комплексом Бозжыра.\n\nЗаповедник — научно-охраняемая территория, а не туристический объект. Для входа нужно предварительное разрешение Комитета лесного хозяйства и животного мира и либо местный оператор, либо собственный гид заповедника — "с улицы" не пускают. На практике подходит тем, кто целенаправленно едет за специализированным наблюдением за дикой природой и готов заранее пройти бюрократию.',
      kk: '1984 жылы Қарақия ауданында, Үстірт үстіртінің оңтүстік шетінде құрылған 223 000 гектарлық мемлекеттік табиғи қорық. Орталық Азияның нағыз шөл және құрғақ дала экожүйелерін қорғайды: үстірт құланы (уриал), қарақұйрық (жейран), киік, қарақұлақ және тарихта жолбарыс. Ландшафт — тік жарлы әктас үстірт, бұл одан солтүстіктегі Бозжыра шатқалдарынан бөлек.\n\nҚорық — туристік нысан емес, ғылыми қорғалатын аумақ. Кіру үшін Орман шаруашылығы және жануарлар дүниесі комитетінің алдын ала рұқсаты және жергілікті оператор немесе қорықтың өз гиді қажет — өздігінен кіруге болмайды. Іс жүзінде бұл нысан мамандандырылған жабайы табиғат бақылауын қалайтын және алдын ала қағазбастылықпен айналыса алатындарға арналған.',
    },
