        kk: 'Басқыштар жарықтандырылмаған және барлық жерде қоршалмаған — қараңғыдан бұрын төмен түсіңіз; қыста мұздан сақ болыңыз немесе гондоланы пайдаланыңыз. Жоғарыда қаладан шамамен +10 °C салқын, желді.',
