    coords: { lat: 43.2252, lng: 77.8716 },
    shortDescription: {
      fi: 'Korkea kesälaidun ~2700 m:ssä Almatysta itään — jurttoja, hevoslaumoja ja Tien Shanin tähtitaivas.',
      en: 'A high summer pasture at around 2,700 m east of Almaty — yurts, herds of horses and Tien Shan starry skies.',
      ru: 'Высокогорное летнее пастбище на ~2 700 м к востоку от Алматы — юрты, табуны лошадей и тянь-шаньское звёздное небо.',
      kk: 'Алматыдан шығысқа қарай, шамамен 2 700 м биіктіктегі биік жайлау — киіз үйлер, жылқы үйірлері және Тянь-Шань жұлдызды аспаны.',
    },
    description: {
      fi: 'Loivien vihreiden mäkien rajaama jailoo eli kazakkilainen kesälaidun yli puurajan, n. 100 km Almatysta itään. Kesäisin paimentolaisten jurttoja, hevoslaumoja ja lampaita avaralla horisontilla. Tasangolla sijaitsee myös Assy–Turgenin tähtitieteellinen observatorio (≈2750 m), ja korkeuden + valosaasteettomuuden ansiosta tähtitaivas on poikkeuksellisen kirkas.\n\nPääsy vie Turgenin laaksosta jyrkän Assyn solan (Asy Pass) yli — tie on soraa ja vaatii käytännössä 4WD:n. Talvella tie on kiinni, joten kohde on kesäkohde kesäkuusta syyskuuhun.',
      en: 'A jailau — a Kazakh summer pasture — framed by gentle green hills above the tree line, about 100 km east of Almaty. In summer, nomadic yurts, horse herds and sheep fill the open horizon. The plateau also hosts the Assy–Turgen astronomical observatory (≈2,750 m); thanks to the altitude and absence of light pollution, the night sky is exceptionally clear.\n\nAccess runs from the Turgen valley over the steep Asy Pass — a gravel road that effectively requires a 4WD. The road is closed in winter, so this is a summer destination from June to September.',
      ru: 'Джайлау — казахское летнее пастбище — обрамлённое пологими зелёными холмами выше границы леса, примерно в 100 км к востоку от Алматы. Летом на широком горизонте — юрты кочевников, табуны лошадей и отары овец. На плато находится астрономическая обсерватория Ассы–Тургень (~2 750 м); благодаря высоте и отсутствию светового загрязнения звёздное небо исключительно яркое.\n\nДорога идёт из долины Тургеня через крутой перевал Ассы — гравийную трассу, для которой фактически нужен полный привод. Зимой дорога закрыта, поэтому маршрут летний, с июня по сентябрь.',
      kk: 'Алматыдан шығысқа қарай шамамен 100 км жерде, орман шегінен жоғарыда орналасқан, көк белесті жатық төбелер қоршаған жайлау. Жазда көшпелілердің киіз үйлері, жылқы үйірлері мен қой отарлары кең көкжиекті толтырады. Үстіртте Ассы–Түрген астрономиялық обсерваториясы (≈2 750 м) да бар; биіктік пен жарық ластануының жоқтығының арқасында жұлдызды аспан ерекше жарқын.\n\nЖол Түрген аңғарынан тік Ассы асуы арқылы өтеді — қиыршық тас жол, іс жүзінде 4WD қажет. Қыста жол жабық, сондықтан бұл — маусым–қыркүйек аралығындағы жазғы бағыт.',
    },
