    shortDescription: {
      fi: 'Ustyurtin reunan jyrkänteeltä avautuu näkymä Karynzharyqin syvälle alangolle ja sen "Kolmen veljen" -kalliopilareille.',
      en: 'From the edge of the Ustyurt chink a sweeping view opens onto the deep Karynzharyq depression and its "Three Brothers" rock pillars.',
      ru: 'С обрыва чинка Устюрта открывается вид на глубокую впадину Карынжарык и её скальные останцы "Три брата".',
      kk: 'Үстірт жарының шетінен Қарынжарық ойпатына және оның «Үш Ағайынды» жартас бағаналарына кең көрініс ашылады.',
    },
    description: {
      fi: 'Karynzharyq on noin 85 km pitkä eroosiopainanne eteläisessä Mangystaussa, jonka pohja vajoaa paikoin 75 m merenpinnan alapuolelle. Ustyurtin länsireunan ("chink") jyrkänteeltä avautuu laaja panoraama suolatasangolle ja sen yksinäisille "Kolmen veljen" (Üş Ağaiyndy) -kalliosaarille, jotka nousevat noin 116 m alangosta.\n\nNäköalapaikka on suosittu valokuvauspysähdys 4WD-kierroksilla, jotka tulevat tyypillisesti Bozzhyran tai Tuzbairin suunnasta. Rakennettua tasannetta ei ole — paras katselupiste on jyrkänteen reuna, joten ole varovainen tuulella ja löyhän hiekkakiven päällä.',
      en: 'Karynzharyq is an erosion depression about 85 km long in southern Mangystau whose floor drops in places to 75 m below sea level. From the edge of the western Ustyurt "chink" a wide panorama opens onto the salt flat and its solitary "Three Brothers" (Üş Ağaiyndy) rock outcrops, which rise some 116 m from the lowland.\n\nThe viewpoint is a popular photo stop on 4WD loops that typically come in from Bozzhyra or Tuzbair. There is no built platform — the best vantage is the very edge of the cliff, so be careful in the wind and on the friable sandstone.',
      ru: 'Карынжарык — эрозионная впадина протяжённостью около 85 км на юге Мангистау, дно которой местами опускается до 75 м ниже уровня моря. С обрыва западного чинка Устюрта открывается широкая панорама на солончак и одиночные скальные останцы "Три брата" (Үш Ағайынды), поднимающиеся над низиной примерно на 116 м.\n\nСмотровая площадка — популярная фотопауза на 4WD-маршрутах, идущих обычно со стороны Бозжыры или Тузбаира. Никакой обустроенной площадки нет — лучшая точка наблюдения это сам край обрыва, поэтому будьте осторожны на ветру и на рыхлом песчанике.',
      kk: 'Қарынжарық — Маңғыстаудың оңтүстігіндегі шамамен 85 км ұзындықтағы эрозиялық ойпат, түбі жекелеген жерлерде теңіз деңгейінен 75 м төмен түседі. Үстірттің батыс жарының («чинк») жиегінен тұзды жазыққа және ойпаттан шамамен 116 м биіктеген жалғыз тұрған «Үш Ағайынды» жартас қалдықтарына кең көрініс ашылады.\n\nШолу нүктесі — әдетте Бозжыра немесе Тұзбайыр жағынан келетін 4WD сапарларының танымал фото-аялдамасы. Арнайы алаң жоқ — ең жақсы көрініс жардың дәл шетінен ашылады, сондықтан желде және борпылдақ құмтаста абай болыңыз.',
    },
