      en: 'A small alpine lake (~3,112 m) high in the Zailiysky Alatau at the head of the Issyk River, known for its bright turquoise water and the snowy peaks ringing it. It lies inside the Almaty Nature Reserve in Talgar district.\n\nIt is not on the standard tourist circuit — reaching it requires a reserve entry permit, several hours of hiking and a head for altitude. There is no free vehicle access; from the ranger station the hike typically takes several hours each way.',
      ru: 'Небольшое высокогорное озеро (≈ 3 112 м) в Заилийском Алатау, в верховьях реки Иссык, известное ярко-бирюзовой водой и кольцом снежных вершин вокруг. Находится в Алматинском заповеднике, в Талгарском районе.\n\nЭто не стандартный туристический маршрут — нужны разрешение заповедника, многочасовой треккинг и устойчивость к высоте. Свободного подъезда на машине нет; от поста егеря пешком, как правило, несколько часов в одну сторону.',
