        kk: 'Қозғалыс — белгіленген соқпақсыз етектерімен қысқа серуен (2–3 км, 1–3 сағат); мұнаралардың түбінен тас суреттер мен қазба қалдықтарды іздеңіз — өрмелеуге тыйым салынған, жұмсақ бор үгітіледі.',
