      ru: 'Маленькая обжарка-эспрессо-бар на улице Кабанбай батыра, открытая в 2016 году голландско-индонезийским бариста Матайсом Антоном Олием. Пожалуй, самый стабильно хвалимый specialty-кофе в городе: эспрессо моносортов, V60 и кортадо — беспроигрышный выбор, на витрине — местные голландские пирожные. Попал в гид European Coffee Trip — заходите на короткий утренний или дневной кофе, а не на долгие посиделки.',
      kk: 'Қабанбай батыр көшесіндегі шағын қуыру цехы әрі эспрессо-бар, оны 2016 жылы голланд-индонезиялық бариста Матайс Антоон Олий ашқан. Қаладағы тұрақты түрде ең көп мақталатын specialty кофе: бір тектілі эспрессо, V60 және кортадо — сенімді таңдау, витринада жергілікті жасалған голланд тоқаштары. European Coffee Trip-тің specialty гидіне енген — ұзақ отыруға емес, таңертеңгі немесе түстен кейінгі қысқа кофе үшін кіріңіз.',
