    coords: { lat: 43.2563, lng: 76.9499 },
    shortDescription: {
      fi: 'Almatyn tunnetuin georgialainen ravintola Kunayev-kadulla — khachapuri savitulesta ja käsin taiteltu khinkali.',
      en: 'Almaty\'s best-known Georgian restaurant on Kunayev street — clay-oven khachapuri and hand-folded khinkali.',
      ru: 'Самый известный грузинский ресторан Алматы на улице Кунаева — хачапури из тонэ и лепные хинкали.',
      kk: 'Алматыдағы ең танымал грузин мейрамханасы Қонаев көшесінде — балшық пешінен пісірілген хачапури және қолмен бүктелген хинкали.',
    },
    description: {
      fi: 'Daredzhani on vakiintunut viittauspiste georgialaisesta keittiöstä Almatyssa. Sali on rakennettu Kakhetin maaseututaloksi — puupalkit, savitiilet, viinitynnyrit — ja menu pysyy klassikoissa: Adjarian khachapuri (venepuristeinen juusto-munaleipä) tulee savitulesta, khinkalit taitellaan käsin, ostri-pataa keitetään tomaatti-paprikakastikkeessa. Viinilista nojaa Saperaviin ja Rkatsiteliin Kakhetian tarhoilta. Kohde heijastaa Almatyn kohtuullisen suurta kaukasialaista diasporaa: kaupunki on ollut vuosikymmeniä koti Georgian, Armenian ja Azerbaidžanin yhteisöille, ja keittiöt ovat nousseet osaksi paikallista syömiskulttuuria.',
      en: 'Daredzhani is the established reference point for Georgian cuisine in Almaty. The room is built like a Kakheti farmhouse — wooden beams, clay tiles, wine barrels — and the menu sticks to the classics: Adjarian khachapuri (the boat-shaped cheese-and-egg bread) from a clay oven, hand-folded khinkali, ostri stewed in tomato-pepper sauce. The wine list leans on Saperavi and Rkatsiteli from Kakhetian vineyards. The restaurant reflects Almaty\'s sizeable Caucasian diaspora — the city has been home to Georgian, Armenian and Azerbaijani communities for decades, and their kitchens have become a fixture of how the city eats.',
      ru: 'Дареджани — устоявшаяся точка отсчёта грузинской кухни в Алматы. Зал оформлен под кахетинский деревенский дом — деревянные балки, глиняная плитка, винные бочки, — а меню держится за классику: аджарский хачапури (лодочка с сыром и яйцом) из глиняной печи тонэ, лепные хинкали, остри в томатно-перечном соусе. Винная карта построена вокруг Саперави и Ркацители из кахетинских хозяйств. Заведение отражает заметную кавказскую диаспору Алматы — десятилетиями в городе живут грузинские, армянские и азербайджанские общины, и их кухни давно стали частью местной гастрономии.',
      kk: 'Дареджани — Алматыдағы грузин асханасының қалыптасқан өлшемі. Зал Кахети ауыл үйі сияқты безендірілген — ағаш арқалықтар, балшық плиткалар, шарап күбілері — ал мәзір классикадан ауытқымайды: балшық пеште пісірілген аджар хачапуриі (қайық пішінді ірімшік-жұмыртқа нан), қолмен бүктелген хинкали, қызанақ-бұрыш тұздығындағы остри. Шарап тізімі Кахети жүзімдіктерінен жиналған Сапераві мен Рқацителиге сүйенеді. Мейрамхана Алматыдағы айтарлықтай үлкен кавказ диаспорасын көрсетеді — қала ондаған жылдар бойы грузин, армян және әзірбайжан қауымдастықтарының үйі болған, ал олардың асханалары жергілікті тағам мәдениетінің бір бөлігіне айналған.',
    },
