    shortDescription: {
      fi: 'Modernin tulkinnan kazakhilaisruoka maltillisin hinnoin — Keruen-ostari vastapäätä, kilometrin päässä Baiterekistä.',
      en: 'Modern takes on Kazakh classics at sensible prices — across the road from Keruen mall, a kilometre from Bayterek.',
      ru: 'Современная казахская кухня по умеренным ценам — напротив ТРЦ «Керуен», в километре от Байтерека.',
      kk: 'Қазақ тағамдарының заманауи нұсқалары қолжетімді бағамен — «Керуен» сауда орталығының қарсысында, Бәйтеректен бір шақырым жерде.',
    },
    description: {
      fi: 'Saksaul on Astanan käytännöllisin osoite kazakhilaiseen ruokaan: aitoa keittiötä avoimella tulisijalla (tandoor, grilli ja kazan-pata näkyvissä salista), jurttaa muistuttavaksi modernisoitu sisustus ja menu joka kattaa klassikot — beshbarmak, hevoslihanuudelikeitto, kuyrdak (lampaan sisuselinpata), pilahvi, šašlik, samsa ja kumiss-jäätelö jälkiruoaksi. Annokset ovat reiluja ja keskimääräinen lasku jää 6 000–7 000 KZT henkilöltä, mikä tekee tästä huomattavasti saavutettavamman vaihtoehdon kuin Qazaq Gourmet tai Selfie.\n\nSijainti on Dostyk-katu 5, "Pohjoinen Sija" -asuintornin alakerrassa Esilin (Vasen ranta) kaupunginosassa — kävellen Baiterek-tornilta noin 15 minuuttia. TripAdvisorissa 4,7/5 (437 arvostelua, #6 koko Astanassa) ja Yandexissä 5,0/5 yli 4 100 äänellä — paikallinen yleisö on löytänyt paikan, ei pelkkä turistipysähdys.',
      en: 'Saksaul is Astana\'s most practical address for Kazakh food: an authentic kitchen with an open hearth (tandoor, grill and a cauldron all visible from the dining room), a yurt-inspired modern interior and a menu that covers the classics — beshbarmak, horsemeat noodle soup, kuyrdak (lamb organ stew), pilaf, shashlik, samsa and kumiss ice cream for dessert. Portions are generous and the average bill stays around 6,000–7,000 KZT per head, which makes it far more accessible than Qazaq Gourmet or Selfie.\n\nThe address is Dostyk 5, on the ground floor of the "Northern Lights" residential tower in the Esil (Left Bank) district — about a 15-minute walk from Bayterek Tower. TripAdvisor 4.7/5 with 437 reviews (#6 of 1,162 in Astana) and Yandex 5.0/5 with over 4,100 ratings — local diners have found the place, it\'s not just a tourist stop.',
      ru: 'Саксаул — самый практичный адрес в Астане для казахской кухни: настоящая кухня с открытым очагом (тандыр, мангал и казан видны прямо из зала), современный интерьер с юртными мотивами и меню классики — бешбармак, лапша на конине, куырдак (рагу из бараньих субпродуктов), плов, шашлык, самса и мороженое с кумысом на десерт. Порции щедрые, средний чек держится около 6 000–7 000 KZT с человека — заметно доступнее, чем Qazaq Gourmet или Selfie.\n\nАдрес: Достык 5, на первом этаже ЖК «Северное Сияние» в Есильском районе (левый берег) — примерно 15 минут пешком от Байтерека. На TripAdvisor 4,7/5 (437 отзывов, #6 из 1 162 в Астане), на Яндексе 5,0/5 при более 4 100 оценках — место нашли местные, это не только туристическая остановка.',
      kk: 'Сексеуіл — Астанадағы қазақ асханасына барудың ең қолайлы мекенжайы: ашық ошақты нағыз асхана (тандыр, мангал және қазан залдан көрініп тұрады), юрт мотивтеріндегі заманауи интерьер және классиканы қамтитын мәзір — бешбармақ, жылқы етінен дайындалған кеспе сорпасы, қуырдақ (қой ішек-қарын паудасы), палау, шашлық, самса және десертке қымыз балмұздақ. Порциялар үлкен, орташа шек адамына 6 000–7 000 KZT шамасында — Qazaq Gourmet немесе Selfie-ге қарағанда әлдеқайда қолжетімді.\n\nМекенжайы: Достық көшесі 5, «Солтүстік Сияния» тұрғын үй кешенінің бірінші қабатында, Есіл ауданында (сол жаға) — Бәйтерек монументінен жаяу шамамен 15 минут. TripAdvisor-да 4,7/5 (437 пікір, Астанадағы 1 162 мейрамхана ішінен #6), Яндексте 5,0/5, 4 100-ден астам бағамен — орынды жергіліктілер тапқан, бұл тек турист бекеті емес.',
    },
