    coords: { lat: 51.1081, lng: 71.4304 },
    shortDescription: {
      fi: 'Astanan ensimmäinen kazakkilaisen haute-keittiön fine dining -ravintola — La Liste 2025 Top 1000 ja World\'s 50 Best Discovery.',
      en: 'Astana\'s first haute-Kazakh fine-dining restaurant — on La Liste 2025 Top 1000 and a World\'s 50 Best Discovery.',
      ru: 'Первый ресторан высокой казахской кухни в Астане в формате fine dining — La Liste 2025 Top 1000 и World\'s 50 Best Discovery.',
      kk: 'Астанадағы алғашқы қазақы haute-асханасы бағытындағы fine dining мейрамханасы — La Liste 2025 Top 1000 және World\'s 50 Best Discovery тізімінде.',
    },
    description: {
      fi: 'Qazaq Gourmet on käytännössä ensimmäinen ravintola, joka tarjoaa kazakkilaista keittiötä haute cuisine -tasolla Astanassa. Keittiötä johtaa Artem Kantsev, joka on kiertänyt maan eri alueita kerätäkseen perinneraaka-aineita ja -tekniikoita ja kääntää ne moderniksi tarjoiluksi: lampaan ja kurpitsan manti, lammas savustetulla munakoisolla, taateleilla ja narsharab-kastikkeella, beldeme-pihvi hevoslihasta, sammella tehty fishbarmak ja hitaasti haudutettu lammas.\n\nSali on tunnistettava — punaoranssi väripaletti, kupolimainen katto, kristallikruunut ja vitriineissä historiallisia kazakkiasuja. Paikka on listattu La Liste 2025 Top 1000 -listalle 76 pisteellä (yksi vain neljästä kazakstanilaisesta ravintolasta listalla) ja World\'s 50 Best Discoveryyn, ja Astana Times nosti sen omaksi jutuksi tammikuussa 2024.\n\nSijainti on Mangilik El -kadulla 29, House of Ministries -korttelissa Esilin piirissä Vasemmalla rannalla. Käytännössä destinaatioravintola — ei ohimennen, vaan illan ohjelma.',
      en: 'Qazaq Gourmet is effectively the first restaurant serving Kazakh cuisine at haute-cuisine level in Astana. The kitchen is led by chef Artem Kantsev, who travelled the country to research regional Kazakh ingredients and techniques and turn them into modern plates: mutton and pumpkin dumplings, lamb with smoked aubergine, dates and narsharab sauce, beldeme steak from horse meat, fishbarmak with sturgeon and slow-cooked lamb.\n\nThe dining room is unmistakable — scarlet-orange palette, a domed ceiling, chandeliers and display cases of historic Kazakh costumes. The restaurant made La Liste 2025 Top 1000 with 76 points (one of only four Kazakh restaurants on the list) and the World\'s 50 Best Discovery selection, and Astana Times ran a dedicated feature in January 2024.\n\nThe address is Mangilik El Avenue 29, in the House of Ministries block in the Esil district on the Left Bank. In practice this is a destination restaurant — not a casual drop-in but the evening\'s plan.',
      ru: 'Qazaq Gourmet — фактически первый ресторан в Астане, подающий казахскую кухню на уровне haute cuisine. Кухню ведёт шеф Артём Канцев, который объездил регионы страны, изучая традиционные продукты и техники, и переводит их в современную подачу: манты с бараниной и тыквой, баранина с копчёным баклажаном, финиками и соусом наршараб, стейк бельдеме из конины, фишбармак с осетриной и долго томлёная баранина.\n\nЗал узнаваемый — алая палитра, купольный потолок, люстры и витрины с историческими казахскими костюмами. Заведение вошло в La Liste 2025 Top 1000 с 76 баллами (один из всего четырёх казахстанских ресторанов в списке) и в подборку World\'s 50 Best Discovery, а Astana Times посвятила ему отдельный материал в январе 2024.\n\nАдрес — проспект Мәңгілік Ел 29, в квартале Дома министерств в Есильском районе на Левом берегу. По сути ресторан-направление — не «зайти мимоходом», а план на вечер.',
      kk: 'Qazaq Gourmet — Астанадағы қазақ асханасын haute cuisine деңгейінде ұсынатын алғашқы мейрамхана. Аспазшы — Артём Канцев, ол ел өңірлерін аралап дәстүрлі өнімдер мен әдістерді зерттеп, оларды заманауи тағамдарға айналдырған: қой еті мен асқабақтан мәнті, ысталған бадырған, құрма мен наршараб тұздығымен қой еті, жылқы етінен бельдеме стейк, бекіремен жасалған фишбармақ және ұзақ бұқтырылған қой еті.\n\nЗал бірден танылады — қызыл-қызғылт сары палитра, күмбез төбе, люстралар және тарихи қазақ киімдері қойылған витриналар. Мейрамхана 76 ұпаймен La Liste 2025 Top 1000 тізіміне енген (тізімдегі бар-жоғы төрт қазақстандық мейрамхананың бірі) және World\'s 50 Best Discovery таңдауында, ал Astana Times 2024 жылдың қаңтарында жеке материал шығарды.\n\nМекенжайы — Мәңгілік Ел даңғылы 29, Сол жағалаудағы Есіл ауданындағы Министрліктер үйі кварталында. Бұл нағыз бағытталған мейрамхана — жолшыбай кіретін жер емес, кешкі жоспардың өзі.',
    },
