    shortDescription: {
      fi: 'Kazakstanin ensimmäinen kokeellinen cocktailbaari ilman menua — varaus pakollinen, sijainti piilotettu.',
      en: "Kazakhstan's first experimental cocktail bar with no menu — reservation required, hidden entrance.",
      ru: 'Первый экспериментальный коктейль-бар Казахстана без меню — нужна бронь, вход скрытый.',
      kk: 'Қазақстандағы алғашқы эксперименталды коктейль бары — мәзірі жоқ, брондау міндетті, кіреберіс жасырын.',
    },
    description: {
      fi: 'Temple on Kazakstanin ensimmäinen kokeellinen cocktailbaari ja klassinen speakeasy: lukittu ovi, ei kylttiä, sisäänpääsy vain varauksella (Instagram, Telegram tai WhatsApp). Menua ei ole — kerrotte baarimikolle mielialanne ja makumieltymyksenne, ja toisen kerroksen cocktail-labrassa rakennetaan teille räätälöity drinkki talon omilla tinktuureilla, bittereillä ja uutteilla. Keittiötä ei ole, paikka on puhtaasti miksologiaan keskittyvä.\n\nSisustus on Kvadrat Architectsin palkittu työ vuodelta 2023 ja paikka on World\'s 50 Best Discovery -listalla. Tunnusmerkki on baaritiskin yllä riippuva 150 vuotta vanha puunjuuri, joka tuotiin Petropavlovskista. Osoite on Akhmet Baytursynov 3:n toinen kerros keskustassa Hazrat Sultan -moskeijan, Shabyt-taidepalatsin ja RC Highvillen lähellä — kävelymatkan päässä vasemman rannan päänähtävyyksistä mutta löytyy vain jos tietää tarkalleen mihin ovea koputtaa.',
      en: "Temple is Kazakhstan's first experimental cocktail bar and a proper speakeasy: a locked door, no signage, entry by reservation only (via Instagram, Telegram or WhatsApp). There is no menu — you tell the bartender your mood and preferences, and the second-floor cocktail lab builds you a bespoke drink using house tinctures, bitters and extracts. There is no kitchen; the place is purely about mixology.\n\nThe interior is an award-winning 2023 design by Kvadrat Architects, and the bar holds a World's 50 Best Discovery listing. Its defining feature is a 150-year-old tree root suspended above the bar, brought from Petropavlovsk. The address is the 2nd floor of Akhmet Baytursynov 3 in central Astana, near Hazrat Sultan Mosque, the Shabyt Palace of Arts and RC Highville — within walking distance of the Left Bank's main sights, but only findable if you know exactly which door to knock on.",
      ru: 'Temple — первый экспериментальный коктейль-бар Казахстана и настоящий спикизи: запертая дверь, никаких вывесок, вход только по брони (Instagram, Telegram или WhatsApp). Меню нет — вы рассказываете бармену про настроение и предпочтения, а в коктейльной лаборатории на втором этаже вам делают индивидуальный напиток на домашних настойках, биттерах и экстрактах. Кухни нет, заведение полностью про миксологию.\n\nИнтерьер — отмеченная наградами работа Kvadrat Architects 2023 года, бар включён в World\'s 50 Best Discovery. Главная фишка — корень 150-летнего дерева, подвешенный над барной стойкой и привезённый из Петропавловска. Адрес — Ахмет Байтұрсынұлы 3, 2-й этаж в центре Астаны рядом с мечетью Хазрет Султан, Дворцом искусств «Шабыт» и ЖК Highvill — в пешей доступности от главных видов Левого берега, но найти можно, только если знаешь, в какую именно дверь стучать.',
      kk: 'Temple — Қазақстандағы алғашқы эксперименталды коктейль бары және нағыз speakeasy: құлыпталған есік, маңдайша жоқ, кіру тек брондау арқылы (Instagram, Telegram немесе WhatsApp). Мәзір жоқ — бармейстерге көңіл-күйіңіз бен талғамыңызды айтасыз, ал екінші қабаттағы коктейль зертханасында үй тұнбалары, биттерлер мен экстракттардан жеке сусын дайындалады. Асхана жоқ, орын тек миксологияға арналған.\n\nИнтерьер — Kvadrat Architects сәулет бюросының 2023 жылғы марапатқа ие жобасы, бар World\'s 50 Best Discovery тізімінде. Басты белгі — бар үстелінің үстіне ілінген, Петропавлдан әкелінген 150 жылдық ағаш тамыры. Мекенжайы — Ахмет Байтұрсынұлы көшесі 3, Астана орталығындағы 2-қабат, Хазірет Сұлтан мешіті, «Шабыт» өнер сарайы және Highvill тұрғын кешені жанында — Сол жағалаудың басты көрікті жерлерінен жаяу қашықтықта, бірақ оны қай есікті қағу керектігін білген адам ғана таба алады.',
    },
