    shortDescription: {
      fi: 'Aqtaun johtava gastropub Che Guevara -teemoituksella, live-musiikkia klo 22:n jälkeen.',
      en: 'Aktau\'s leading gastropub with a Che Guevara theme and live music after 22:00.',
      ru: 'Ведущий гастропаб Актау в стиле Че Гевары, живая музыка после 22:00.',
      kk: 'Ақтаудың жетекші гастропабы Че Гевара тақырыбында, 22:00-ден кейін жанды музыка.',
    },
    description: {
      fi: 'Chechil on Aqtaun ylivoimainen ykkösgastropub ja samalla kaupungin lähin "ilta-destinaatio" — Che Guevara -teemoitettu sisustus, noin 450 hengen kapasiteetti, tanssitila ja oma lava. Tarjolla on laaja juomalista paikallisia kazakkilaisia oluita, cocktaileja ja viinejä myöten sekä tukeva ruokamenu, joten paikka toimii sekä illalliselle että iltamyöhälle. Sijainti on keskustassa rantakadun läheisyydessä (7А mikrorajon, 6).\n\nLive-musiikki alkaa illalla klo 22:n jälkeen, ja silloin paikka muuttuu pubista lavakeskeiseksi musiikkibaariksi — ei kuitenkaan klubiksi. Tunnelma on rento mutta tarjoaa tarpeeksi tilaa myös smart-casual -pukeutumiselle, ja yleisö on Aqtaun mittakaavassa laaja: ei pelkkä öljytyöläispubi. 2GIS:ssä paikka kerää 4,7/5 (1 483 arvostelua, 658 kirjoitettua palautetta) ja TripAdvisorissa #1 Aqtaun baareista — ylivoimaisesti validoiduin yöelämäkohde kaupungissa.',
      en: 'Chechil is Aktau\'s clear number-one gastropub and the closest thing the city has to a destination nightlife venue — Che Guevara-themed decor, a capacity of about 450, a dance floor and an in-house stage. The drink list is broad, covering local Kazakh beers, cocktails and wines, and the kitchen is solid enough that the place works for both dinner and a late evening. Location is central, near the seafront (Microdistrict 7А, 6).\n\nLive music starts after 22:00, when the venue shifts from gastropub to stage-driven music bar — though it never becomes a club. The vibe is relaxed but leaves room for smart-casual dress, and the crowd is unusually broad for Aktau: this is not just an oil-worker pub. On 2GIS the place pulls 4.7/5 (1,483 ratings, 658 written reviews) and ranks #1 among Aktau\'s bars and pubs on TripAdvisor — by far the most-validated nightlife venue in the city.',
      ru: 'Чечил — безоговорочный гастропаб №1 в Актау и ближайшее, что есть в городе к «вечерней точке притяжения»: интерьер в стиле Че Гевары, вместимость около 450, танцпол и собственная сцена. Барная карта широкая — местное казахстанское пиво, коктейли, вино, а кухня достаточно крепкая, чтобы провести здесь и ужин, и поздний вечер. Расположение центральное, рядом с набережной (7А микрорайон, 6).\n\nЖивая музыка начинается после 22:00 — заведение превращается из гастропаба в музыкальный бар вокруг сцены, но клубом не становится. Атмосфера спокойная, но допускает smart-casual, а публика для Актау на редкость разнообразная: это не просто паб для нефтяников. На 2GIS — 4,7/5 (1 483 оценки, 658 отзывов), на TripAdvisor — №1 среди баров и пабов Актау; самое подтверждённое отзывами вечернее заведение города с большим отрывом.',
      kk: 'Чечил — Ақтаудың айқын №1 гастропабы әрі қаладағы ең «кешкі дестинацияға» жақын орын: Че Гевара тақырыбындағы интерьер, шамамен 450 адамға арналған сыйымдылық, би алаңы және өз сахнасы. Сусындар тізімі кең — жергілікті қазақ сыралары, коктейльдер мен шараптар, ал асүй кешкі ас пен кешкі отыруға бірдей жарайды. Орналасуы орталықта, жағалауға жақын (7А ықшамаудан, 6).\n\nЖанды музыка 22:00-ден кейін басталады, сонда орын гастропабтан сахна айналасындағы музыкалық барға айналады — бірақ клубқа емес. Көңіл-күй жайбарақат, бірақ smart-casual киім үшін де орын бар, ал Ақтау ауқымында жұртшылық таңғаларлықтай әртүрлі: бұл жай ғана мұнайшылар пабы емес. 2GIS-те 4,7/5 (1 483 баға, 658 пікір) және TripAdvisor-да Ақтаудың барлары мен пабтары арасында №1 — қаладағы ең көп растамасы бар түнгі орын, үлкен айырмамен.',
    },
