      fi: 'Azerbaidžanilainen ravintola jossa tarjoillaan fishbarmakia — Mangystaun erikoisuutta jota ei ole muualla Kazakstanissa.',
      en: 'Azerbaijani restaurant serving fishbarmak — a Mangystau speciality you will not find elsewhere in Kazakhstan.',
      ru: 'Азербайджанский ресторан, где подают фишбармак — мангистаускую особенность, которой больше нигде в Казахстане нет.',
      kk: 'Азербайжан мейрамханасы, мұнда Қазақстанның басқа жерінде жоқ Маңғыстаудың ерекшелігі — фишбармақ ұсынылады.',
