    description: {
      fi: 'Narsharab on kaukasialainen, vahvasti azerbaidžanilainen kafé-ravintola ZhK Kaspiy -korttelissa Aktaun 16. mikrorajonissa. Nimi tulee narsharabista — paksusta granaattiomenakastikkeesta jota tarjoillaan klassisesti Kaspian sammen kanssa. Talon erikoisuus on fishbarmak: Mangystaun oma kalaversio beshbarmakista, jota ei tehdä missään muualla Kazakstanissa. Sen lisäksi listalla on sampi-shashlik narsharab-kastikkeella, kutab-leivoksia ja täytetty dolma.\n\nPaikka on 2GIS:n mukaan vahvasti arvioitu (4,7/5 noin 300 arviolla, joista yli 170 kirjoitettua) — Aktaun mittakaavassa huipputason validointi. Aktiivinen toiminta on vahvistettu Woltin ja Instagramin (@narsharab_aktau) kautta, aukioloajat 11:00–01:00 päivittäin. Hyvä illallisvalinta promenadin tai kaupunkikävelyn jälkeen, kun haluatte kokeilla nimenomaan Mangystaun paikallista erikoisruokaa eikä geneeristä shashlik-listaa.',
      en: 'Narsharab is a Caucasian, strongly Azerbaijani cafe-restaurant in the ZhK Kaspiy block in Aktau\'s 16th microdistrict. The name comes from narsharab — the thick pomegranate sauce classically served with Caspian sturgeon. The house speciality is fishbarmak: Mangystau\'s own fish version of beshbarmak, made nowhere else in Kazakhstan. The menu also runs to sturgeon shashlik with narsharab sauce, kutab flatbreads and stuffed dolma.\n\nThe restaurant carries strong ratings on 2GIS (4.7/5 across roughly 300 ratings, more than 170 of them written reviews) — top-tier validation at Aktau scale. Active operation is confirmed via Wolt and Instagram (@narsharab_aktau); hours are 11:00–01:00 daily. A good dinner pick after the promenade or a city stroll when you specifically want to try Mangystau\'s local fish dish rather than a generic shashlik menu.',
      ru: 'Narsharab — кавказское, выраженно азербайджанское кафе-ресторан в ЖК «Каспий» в 16-м микрорайоне Актау. Название отсылает к наршарабу — густому гранатовому соусу, который классически подают с каспийским осетром. Фирменное блюдо — фишбармак: мангистауская рыбная версия бешбармака, которой больше нигде в Казахстане не готовят. В меню также шашлык из осетра с наршарабом, кутабы и фаршированная долма.\n\nЗаведение получает высокие оценки на 2GIS (4,7/5 при примерно 300 отзывах, более 170 из них письменных) — для масштабов Актау это сильная валидация. Активная работа подтверждается через Wolt и Instagram (@narsharab_aktau), часы 11:00–01:00 ежедневно. Хороший вариант для ужина после променада или прогулки по городу, когда хочется именно мангистауского рыбного блюда, а не стандартного шашлычного меню.',
      kk: 'Narsharab — Ақтаудың 16-шы шағын ауданындағы «Каспий» ТК-да орналасқан кавказдық, айқын азербайжандық кафе-мейрамхана. Атауы наршарабтан шыққан — Каспий бекіресімен дәстүрлі түрде беріліп жүрген қою анар тұздығынан. Үйдің ерекшелігі — фишбармақ: бесбармақтың Маңғыстауға тән балықтан жасалатын нұсқасы, оны Қазақстанның басқа жерінде дайындамайды. Мәзірде сондай-ақ наршараб тұздығымен бекіре шашлығы, құтаб және толтырылған долма бар.\n\nМейрамхана 2GIS-те жоғары бағаланған (шамамен 300 пікірге 4,7/5, оның 170-тен астамы жазбаша) — Ақтау ауқымында бұл мықты дәлел. Белсенді жұмысы Wolt пен Instagram (@narsharab_aktau) арқылы расталған, жұмыс уақыты күн сайын 11:00–01:00. Жағалаудан немесе қала ішінде серуендеуден кейін, дәл Маңғыстаудың балық тағамын татып көргіңіз келгенде, әдеттегі шашлық мәзірі емес, жақсы кешкі таңдау.',
    },
