    description: {
      fi: 'Daididau on Astanan harvinaisin ravintolakonsepti: laulaja Dimash Kudaibergenin perheen omistama paikka, jossa keittiömestari Nariman Irzhanov soveltaa molekyligastronomiaa ja sous vide -tekniikkaa perinteisiin kazakkilaisiin raaka-aineisiin. Tilaamisen kärkeen kuuluvat perheen oma reseptin beshbarmak smetanan kera, savustetut hevosenkylkiluut, baursaki smetanan kanssa ja kumiss — sekä erikseen oma "special dishes" -menu, jonka kokki rakentaa molekyligastronomian keinoin.\n\nSali toimii myös pienenä musiikkimuseona: Dimashin maailmankiertueilla saamat lahjasoittimet ovat esillä — turkkilainen baglama, indonesialainen sasando, ukrainalainen domra — ja vitriinissä Dimashin kultainen Altyn Adam -lavapuku. Hinta on Astanan fine diningin mittakaavassa maltillinen, keskimäärin 25–30 USD per henkilö, eli selvästi alle Qazaq Gourmetin ja Selfien tason mutta selvästi yli tavallisten kazakkilaiskahviloiden. Osoite on Dinmukhamed Konaev 14, Esilin piirissä Vasemmalla rannalla, alle kilometrin päässä Baiterekistä.',
      en: 'Daididau is Astana\'s most unusual restaurant concept: a venue owned by the family of singer Dimash Kudaibergen, where chef Nariman Irzhanov applies molecular gastronomy and sous vide techniques to traditional Kazakh ingredients. Order the family-recipe beshbarmak with sour cream, smoked horse ribs, baursaki with sour cream and kumiss — and ask for the separate "special dishes" menu the chef builds around molecular gastronomy.\n\nThe dining room doubles as a small music exhibition: instruments gifted to Dimash on his world tours are on display — Turkish baglama, Indonesian sasando, Ukrainian domra — and a glass case holds Dimash\'s golden Altyn Adam-style stage costume. Pricing is moderate by Astana fine-dining standards, around USD 25–30 per head — clearly below Qazaq Gourmet and Selfie but well above standard Kazakh cafés. The address is Dinmukhamed Konaev 14 in the Esil district on the Left Bank, less than a kilometre from Bayterek.',
      ru: 'Daididau — самый необычный ресторанный концепт Астаны: заведение, принадлежащее семье певца Димаша Кудайбергена, где шеф Нариман Иржанов применяет молекулярную гастрономию и су-вид к традиционным казахским продуктам. Берите фирменный семейный бешбармак со сметаной, копчёные конские рёбра, баурсаки со сметаной и кумыс — и попросите отдельное меню «special dishes», которое шеф строит на молекулярной гастрономии.\n\nЗал работает и как небольшая музыкальная экспозиция: на стенах — инструменты, подаренные Димашу в мировых турах: турецкая баглама, индонезийский сасандо, украинская домра, а в витрине — золотой сценический костюм Димаша в стиле Алтын Адам. Цены умеренные по меркам Астанинского fine dining, средний чек около 25–30 USD с человека — заметно ниже Qazaq Gourmet и Selfie, но выше обычных казахских кафе. Адрес: Динмухамеда Конаева 14, Есильский район на Левом берегу, меньше километра от Байтерека.',
      kk: 'Daididau — Астанадағы ең ерекше мейрамхана концепті: әнші Димаш Құдайбергеннің отбасына тиесілі орын, мұнда шеф-аспаз Нариман Иржанов молекулалық гастрономия мен сус-вид әдістерін дәстүрлі қазақ өнімдеріне қолданады. Отбасылық рецептімен сметана қосылған бешбармақ, ысталған жылқы қабырғасы, сметанамен баурсақ және қымыз тапсырыңыз — және шеф молекулалық гастрономия негізінде құрастыратын бөлек «special dishes» мәзірін сұраңыз.\n\nЗал шағын музыкалық экспозиция қызметін де атқарады: қабырғаларда Димашқа дүниежүзілік гастрольдерде сыйға тартылған аспаптар көрсетілген — түрік багламасы, индонезиялық сасандо, украин домрасы — ал витринада Димаштың Алтын Адам үлгісіндегі алтын сахналық киімі тұр. Астана fine dining өлшемінде бағасы қалыпты — адам басына шамамен 25–30 USD, бұл Qazaq Gourmet пен Selfie-ден айтарлықтай төмен, бірақ кәдімгі қазақ дәмханаларынан жоғары. Мекенжайы: Дінмұхамед Қонаев 14, Сол жағалаудағы Есіл ауданында, Бәйтеректен бір шақырымнан жақын.',
    },
